class Allocator {
private:
    std::vector<int> mem;
    int n;
public:
    Allocator(int n) : mem(n, 0), n(n) {}

    int allocate(int size, int mID) {
        int count = 0;
        int start = -1;
        for (int i = 0; i < n; ++i) {
            if (mem[i] == 0) {
                if (count == 0) start = i;
                count++;
                if (count == size) {
                    for (int j = start; j < start + size; ++j) mem[j] = mID;
                    return start;
                }
            } else {
                count = 0;
                start = -1;
            }
        }
        return -1;
    }

    int freeMemory(int mID) {
        int freed = 0;
        for (int i = 0; i < n; ++i) {
            if (mem[i] == mID) {
                mem[i] = 0;
                freed++;
            }
        }
        return freed;
    }
};

class Allocator {
    private int[] mem;
    private int n;

    public Allocator(int n) {
        this.n = n;
        this.mem = new int[n];
    }

    public int allocate(int size, int mID) {
        int count = 0;
        int start = -1;
        for (int i = 0; i < n; i++) {
            if (mem[i] == 0) {
                if (count == 0) start = i;
                count++;
                if (count == size) {
                    for (int j = start; j < start + size; j++) mem[j] = mID;
                    return start;
                }
            } else {
                count = 0;
                start = -1;
            }
        }
        return -1;
    }

    public int freeMemory(int mID) {
        int freed = 0;
        for (int i = 0; i < n; i++) {
            if (mem[i] == mID) {
                mem[i] = 0;
                freed++;
            }
        }
        return freed;
    }
}

var Allocator = function(n) {
    this.n = n;
    this.mem = new Array(n).fill(0);
};

Allocator.prototype.allocate = function(size, mID) {
    let count = 0;
    let start = -1;
    for (let i = 0; i < this.n; i++) {
        if (this.mem[i] === 0) {
            if (count === 0) start = i;
            count++;
            if (count === size) {
                for (let j = start; j < start + size; j++) this.mem[j] = mID;
                return start;
            }
        } else {
            count = 0;
            start = -1;
        }
    }
    return -1;
};

Allocator.prototype.freeMemory = function(mID) {
    let freed = 0;
    for (let i = 0; i < this.n; i++) {
        if (this.mem[i] === mID) {
            this.mem[i] = 0;
            freed++;
        }
    }
    return freed;
};
